#include <iostream>
#include <string>
#include <vector>

int main()
{
    int cap{};
    int m{};
    if (!(std::cin >> cap >> m)) return 0;

    const std::size_t capacity{ static_cast<std::size_t>(cap < 0 ? 0 : cap) };
    std::vector<int> buf(capacity, 0);
    std::size_t head{ 0 };
    std::size_t count{ 0 };

    for (int i = 0; i < m; ++i)
    {
        std::string cmd;
        if (!(std::cin >> cmd)) break;

        if (cmd == "push")
        {
            int x{};
            std::cin >> x;
            if (count == capacity) std::cout << "push full\n";
            else
            {
                buf[(head + count) % capacity] = x;
                ++count;
                std::cout << "push ok\n";
            }
        }
        else if (cmd == "pop")
        {
            if (count == 0) std::cout << "pop empty\n";
            else
            {
                std::cout << "pop " << buf[head] << "\n";
                head = (head + 1) % capacity;
                --count;
            }
        }
        else if (cmd == "front")
        {
            if (count == 0) std::cout << "front empty\n";
            else std::cout << "front " << buf[head] << "\n";
        }
        else if (cmd == "back")
        {
            if (count == 0) std::cout << "back empty\n";
            else std::cout << "back " << buf[(head + count - 1) % capacity] << "\n";
        }
        else if (cmd == "state")
        {
            std::cout << "state head " << head << " size " << count << "\n";
        }
    }

    return 0;
}

