import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    pos = 0
    cap = int(data[pos]); pos += 1
    m = int(data[pos]); pos += 1

    capacity = max(cap, 0)
    buf = [0] * capacity
    head = 0
    count = 0
    out = []

    for _ in range(m):
        if pos >= len(data):
            break
        cmd = data[pos]; pos += 1
        if cmd == "push":
            x = int(data[pos]); pos += 1
            if count == capacity:
                out.append("push full")
            else:
                buf[(head + count) % capacity] = x
                count += 1
                out.append("push ok")
        elif cmd == "pop":
            if count == 0:
                out.append("pop empty")
            else:
                out.append("pop %d" % buf[head])
                head = (head + 1) % capacity
                count -= 1
        elif cmd == "front":
            out.append("front empty" if count == 0 else "front %d" % buf[head])
        elif cmd == "back":
            if count == 0:
                out.append("back empty")
            else:
                out.append("back %d" % buf[(head + count - 1) % capacity])
        elif cmd == "state":
            out.append("state head %d size %d" % (head, count))

    print("\n".join(out))

main()
